for name, s in T.items():
    rows = [tuple(map(int, r.split())) for r in s.split(";")]
    W = sum(r[0] for r in rows); D = sum(r[1] for r in rows); L = sum(r[2] for r in rows)
    ok_rows = all(r[0]+r[1]+r[2] == 8 and 3*r[0]+r[1] == r[3] for r in rows)
    pts = [r[3] for r in rows]
    mono = all(pts[i] >= pts[i+1] for i in range(35))
    print(f"{name}: n={len(rows)} W={W} L={L} (equal={W==L}) D={D} (even={D%2==0}) rows_ok={ok_rows} sorted={mono} "
          f"| 8th={pts[7]} 16th={pts[15]} 24th={pts[23]} | draws/game={D/2/144:.3f} | avg pts={sum(pts)/36:.2f}")
